-- Complete project summaries for all projects
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "24 Provinces", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced families, female-headed households, families of martyrs, and rural communities in 24 provinces."}, "objectives": {"en": "Reduce acute food insecurity among displaced and remote rural households.\nEnsure equitable access to food staples for female-headed and vulnerable families.\nStrengthen community-level distribution mechanisms with local elders and shuras."}, "activities": {"en": "Household vulnerability assessment and beneficiary selection with community shuras.\nProcurement and quality inspection of wheat flour, rice, cooking oil, pulses and salt.\nTransport and last-mile delivery to remote districts using local logistics partners.\nOn-site verification, biometric/photo attendance and post-distribution monitoring."}, "results": {"en": "Basic food baskets delivered to thousands of households across 24 provinces.\nImmediate reduction in negative coping strategies (meal skipping, debt).\nStrengthened community trust and a replicable distribution model for future response."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Food Assistance</strong> portfolio, implemented in <strong>24 Provinces</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>Displaced families, female-headed households, families of martyrs, and rural communities in 24 provinces.</p><h2>Objectives</h2><ul><li>Reduce acute food insecurity among displaced and remote rural households.</li><li>Ensure equitable access to food staples for female-headed and vulnerable families.</li><li>Strengthen community-level distribution mechanisms with local elders and shuras.</li></ul><h2>Key activities</h2><ul><li>Household vulnerability assessment and beneficiary selection with community shuras.</li><li>Procurement and quality inspection of wheat flour, rice, cooking oil, pulses and salt.</li><li>Transport and last-mile delivery to remote districts using local logistics partners.</li><li>On-site verification, biometric/photo attendance and post-distribution monitoring.</li></ul><h2>Results and impact</h2><ul><li>Basic food baskets delivered to thousands of households across 24 provinces.</li><li>Immediate reduction in negative coping strategies (meal skipping, debt).</li><li>Strengthened community trust and a replicable distribution model for future response.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-food24';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Ongoing", "category": "Health & MHPSS", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Mothers, children under five, adolescent girls and survivors of gender-based violence."}, "objectives": {"en": "Improve maternal and child health indicators through community-level education and screening.\nIncrease routine immunization coverage among children in underserved districts.\nProvide accessible mental-health and psychosocial support to women and girls."}, "activities": {"en": "Nutrition education sessions for pregnant and lactating women.\nChild growth monitoring, deworming and routine immunization outreach.\nIndividual and group MHPSS counseling with trained female facilitators.\nReferral pathways to specialised health and protection services."}, "results": {"en": "Hundreds of mothers and children reached with nutrition and health services.\nImproved help-seeking behaviour among women affected by stress and trauma.\nA trained cadre of female counselors sustaining services beyond the project cycle."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Health &amp; MHPSS</strong> portfolio, implemented in <strong>Multi-province</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>Mothers, children under five, adolescent girls and survivors of gender-based violence.</p><h2>Objectives</h2><ul><li>Improve maternal and child health indicators through community-level education and screening.</li><li>Increase routine immunization coverage among children in underserved districts.</li><li>Provide accessible mental-health and psychosocial support to women and girls.</li></ul><h2>Key activities</h2><ul><li>Nutrition education sessions for pregnant and lactating women.</li><li>Child growth monitoring, deworming and routine immunization outreach.</li><li>Individual and group MHPSS counseling with trained female facilitators.</li><li>Referral pathways to specialised health and protection services.</li></ul><h2>Results and impact</h2><ul><li>Hundreds of mothers and children reached with nutrition and health services.</li><li>Improved help-seeking behaviour among women affected by stress and trauma.</li><li>A trained cadre of female counselors sustaining services beyond the project cycle.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-mhpss';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Agriculture", "location": "Rural districts", "country": "Afghanistan", "target_beneficiaries": {"en": "Smallholder farming households, women-headed farming families and returning IDPs."}, "objectives": {"en": "Restore agricultural production capacity in drought and conflict-affected districts.\nDiversify household income through improved crop and orchard varieties.\nBuild farmer knowledge on climate-resilient practices."}, "activities": {"en": "Distribution of certified wheat, vegetable seeds and fruit-tree saplings.\nOn-farm training on land preparation, spacing, irrigation and integrated pest management.\nEstablishment of demonstration plots managed by lead farmers.\nSeason-end yield monitoring and lessons-learned workshops."}, "results": {"en": "Household food production restored for hundreds of smallholder families.\nIncreased dietary diversity from home-grown vegetables and fruit.\nAdoption of improved practices spreading through farmer-to-farmer learning."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Agriculture</strong> portfolio, implemented in <strong>Rural districts</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>Smallholder farming households, women-headed farming families and returning IDPs.</p><h2>Objectives</h2><ul><li>Restore agricultural production capacity in drought and conflict-affected districts.</li><li>Diversify household income through improved crop and orchard varieties.</li><li>Build farmer knowledge on climate-resilient practices.</li></ul><h2>Key activities</h2><ul><li>Distribution of certified wheat, vegetable seeds and fruit-tree saplings.</li><li>On-farm training on land preparation, spacing, irrigation and integrated pest management.</li><li>Establishment of demonstration plots managed by lead farmers.</li><li>Season-end yield monitoring and lessons-learned workshops.</li></ul><h2>Results and impact</h2><ul><li>Household food production restored for hundreds of smallholder families.</li><li>Increased dietary diversity from home-grown vegetables and fruit.</li><li>Adoption of improved practices spreading through farmer-to-farmer learning.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-seeds';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Capacity Building", "location": "National", "country": "Afghanistan", "target_beneficiaries": {"en": "PYECSO female staff, women-led community-based organisations and partner NGOs."}, "objectives": {"en": "Strengthen PYECSO''s institutional systems (finance, HR, safeguarding, M&E).\nBuild the leadership capacity of female staff and community mobilisers.\nImprove compliance with donor and international humanitarian standards."}, "activities": {"en": "Institutional capacity assessment and tailored improvement plan.\nTraining workshops on PSEA, safeguarding, gender-responsive programming and reporting.\nCoaching and mentoring for female team leads.\nRoll-out of updated policies, SOPs and monitoring tools."}, "results": {"en": "Upgraded organisational policies aligned with international standards.\nA stronger pipeline of female managers within PYECSO.\nImproved donor confidence and readiness for larger multi-year grants."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Capacity Building</strong> portfolio, implemented in <strong>National</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>PYECSO female staff, women-led community-based organisations and partner NGOs.</p><h2>Objectives</h2><ul><li>Strengthen PYECSO''s institutional systems (finance, HR, safeguarding, M&amp;E).</li><li>Build the leadership capacity of female staff and community mobilisers.</li><li>Improve compliance with donor and international humanitarian standards.</li></ul><h2>Key activities</h2><ul><li>Institutional capacity assessment and tailored improvement plan.</li><li>Training workshops on PSEA, safeguarding, gender-responsive programming and reporting.</li><li>Coaching and mentoring for female team leads.</li><li>Roll-out of updated policies, SOPs and monitoring tools.</li></ul><h2>Results and impact</h2><ul><li>Upgraded organisational policies aligned with international standards.</li><li>A stronger pipeline of female managers within PYECSO.</li><li>Improved donor confidence and readiness for larger multi-year grants.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-unwomen';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Cash Assistance", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Widows, orphans, daily wage labourers and persons with disabilities during winter months."}, "objectives": {"en": "Prevent seasonal destitution among the most vulnerable during winter.\nEnable households to meet essential needs (food, fuel, warm clothing, medicine).\nProtect children and elderly from cold-related illness and school drop-out."}, "activities": {"en": "Community-based vulnerability targeting with elders, mullahs and female mobilisers.\nMulti-purpose cash transfers via hawala and secure payment agents.\nPost-distribution monitoring and grievance handling."}, "results": {"en": "Winter cash reached hundreds of extremely vulnerable households.\nReduced negative coping (child labour, early marriage, borrowing) reported at PDM.\nDocumented model for rapid, dignified winterisation response."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Cash Assistance</strong> portfolio, implemented in <strong>Multi-province</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>Widows, orphans, daily wage labourers and persons with disabilities during winter months.</p><h2>Objectives</h2><ul><li>Prevent seasonal destitution among the most vulnerable during winter.</li><li>Enable households to meet essential needs (food, fuel, warm clothing, medicine).</li><li>Protect children and elderly from cold-related illness and school drop-out.</li></ul><h2>Key activities</h2><ul><li>Community-based vulnerability targeting with elders, mullahs and female mobilisers.</li><li>Multi-purpose cash transfers via hawala and secure payment agents.</li><li>Post-distribution monitoring and grievance handling.</li></ul><h2>Results and impact</h2><ul><li>Winter cash reached hundreds of extremely vulnerable households.</li><li>Reduced negative coping (child labour, early marriage, borrowing) reported at PDM.</li><li>Documented model for rapid, dignified winterisation response.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-winter';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Livelihoods & TVET", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Women, adolescent girls and young widows with limited access to formal employment."}, "objectives": {"en": "Equip women and adolescents with market-relevant vocational skills.\nEnable dignified home-based and small-workshop income generation.\nSupport economic empowerment and household resilience."}, "activities": {"en": "Tailoring and carpentry courses with certified female and male trainers.\nProvision of starter tool-kits (sewing machines, carpentry tools) on graduation.\nBusiness-skills and financial-literacy modules.\nPost-training follow-up and linkage to local markets."}, "results": {"en": "Graduates launching home-based tailoring and small carpentry enterprises.\nMeasurable increase in reported household income among trained women.\nShift in community attitudes toward women''s economic participation."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Livelihoods &amp; TVET</strong> portfolio, implemented in <strong>Multi-province</strong>. PYECSO — the Patriotic Youths Education, Cultural and Social Organization — is a national, youth-led Afghan NGO working alongside communities, elders and local authorities to design and deliver dignified, community-based responses.</p><h2>Target beneficiaries</h2><p>Women, adolescent girls and young widows with limited access to formal employment.</p><h2>Objectives</h2><ul><li>Equip women and adolescents with market-relevant vocational skills.</li><li>Enable dignified home-based and small-workshop income generation.</li><li>Support economic empowerment and household resilience.</li></ul><h2>Key activities</h2><ul><li>Tailoring and carpentry courses with certified female and male trainers.</li><li>Provision of starter tool-kits (sewing machines, carpentry tools) on graduation.</li><li>Business-skills and financial-literacy modules.</li><li>Post-training follow-up and linkage to local markets.</li></ul><h2>Results and impact</h2><ul><li>Graduates launching home-based tailoring and small carpentry enterprises.</li><li>Measurable increase in reported household income among trained women.</li><li>Shift in community attitudes toward women''s economic participation.</li></ul><h2>Approach</h2><p>All activities are delivered through PYECSO''s community-based approach: participatory targeting with local shuras and female mobilisers, transparent verification, respect for cultural norms, safeguarding of women and children, and post-distribution monitoring feeding back into programme design. PYECSO applies international humanitarian standards (Core Humanitarian Standard, PSEA, and gender-responsive programming) across every project.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='highlight-womentvet';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Cash & In-Kind", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced families and families that lost their primary breadwinner."}, "objectives": {"en": "Protect vulnerable families from cold-related illness during harsh winter.\nPrioritise children, elderly and persons with disability in winter clothing support."}, "activities": {"en": "Procurement of jackets, gloves, boots, blankets and thermal wear.\nCommunity-based targeting and household verification.\nDirect in-kind distribution with dignity-focused site management."}, "results": {"en": "Hundreds of households equipped with essential winter clothing.\nReduced reported cold-related illness among children and elderly."}, "body": {"en": "<h2>Overview</h2><p>This project is part of PYECSO''s <strong>Cash &amp; In-Kind</strong> portfolio, implemented in <strong>Multi-province</strong>. PYECSO delivers dignified in-kind winter support to families most at risk of cold-related harm, including displaced households and families that lost their primary breadwinner.</p><h2>Target beneficiaries</h2><p>Displaced families and families that lost their primary breadwinner.</p><h2>Objectives</h2><ul><li>Protect vulnerable families from cold-related illness during harsh winter.</li><li>Prioritise children, elderly and persons with disability in winter clothing support.</li></ul><h2>Key activities</h2><ul><li>Procurement of jackets, gloves, boots, blankets and thermal wear.</li><li>Community-based targeting and household verification.</li><li>Direct in-kind distribution with dignity-focused site management.</li></ul><h2>Results and impact</h2><ul><li>Hundreds of households equipped with essential winter clothing.</li><li>Reduced reported cold-related illness among children and elderly.</li></ul><h2>Approach</h2><p>PYECSO uses participatory targeting with shuras and female mobilisers, transparent verification and post-distribution monitoring to ensure the right families receive the right items on time.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p1-winter-clothes-distribution';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "Remote rural districts", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced families and remote rural communities beyond regular aid reach."}, "objectives": {"en": "Deliver essential food staples to communities cut off from routine humanitarian response.\nBridge food gaps during lean and post-shock periods."}, "activities": {"en": "Access mapping and negotiation with local authorities and shuras.\nAssembly and transport of food packages to remote delivery points.\nBeneficiary verification, distribution and post-distribution monitoring."}, "results": {"en": "Food assistance reached previously underserved remote communities.\nReduced acute hunger among the most isolated households."}, "body": {"en": "<h2>Overview</h2><p>PYECSO delivers food staples to remote rural districts often bypassed by mainstream humanitarian pipelines, negotiating access through local shuras and pre-positioning stock to bridge critical food gaps.</p><h2>Target beneficiaries</h2><p>Displaced families and remote rural communities beyond regular aid reach.</p><h2>Objectives</h2><ul><li>Deliver essential food staples to communities cut off from routine humanitarian response.</li><li>Bridge food gaps during lean and post-shock periods.</li></ul><h2>Key activities</h2><ul><li>Access mapping and negotiation with local authorities and shuras.</li><li>Assembly and transport of food packages to remote delivery points.</li><li>Beneficiary verification, distribution and post-distribution monitoring.</li></ul><h2>Results and impact</h2><ul><li>Food assistance reached previously underserved remote communities.</li><li>Reduced acute hunger among the most isolated households.</li></ul><h2>Approach</h2><p>Community-based targeting, transparent verification, and PDM are applied on every distribution to safeguard dignity and accountability.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p10-food-distribution-remote-areas';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "24 Provinces", "country": "Afghanistan", "target_beneficiaries": {"en": "Vulnerable households across 24 provinces including displaced, returnee and female-headed families."}, "objectives": {"en": "Provide life-saving food assistance at national scale.\nEstablish an efficient multi-province distribution architecture."}, "activities": {"en": "Centralised procurement with province-level pre-positioning.\nCoordination with provincial authorities and cluster partners.\nSystematic beneficiary selection, distribution and PDM."}, "results": {"en": "National-scale delivery of basic food baskets to vulnerable households.\nDemonstrated PYECSO''s capacity to operate at multi-province scale."}, "body": {"en": "<h2>Overview</h2><p>A nationwide food distribution operation across 24 provinces, combining centralised procurement with province-level pre-positioning and community-based delivery.</p><h2>Target beneficiaries</h2><p>Vulnerable households across 24 provinces including displaced, returnee and female-headed families.</p><h2>Objectives</h2><ul><li>Provide life-saving food assistance at national scale.</li><li>Establish an efficient multi-province distribution architecture.</li></ul><h2>Key activities</h2><ul><li>Centralised procurement with province-level pre-positioning.</li><li>Coordination with provincial authorities and cluster partners.</li><li>Systematic beneficiary selection, distribution and PDM.</li></ul><h2>Results and impact</h2><ul><li>National-scale delivery of basic food baskets to vulnerable households.</li><li>Demonstrated PYECSO''s capacity to operate at multi-province scale.</li></ul><h2>Approach</h2><p>Delivered through PYECSO''s community-based approach with strict safeguarding and PSEA standards throughout the response.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p11-food-distribution-24-provinces';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Livelihoods", "location": "Rural districts", "country": "Afghanistan", "target_beneficiaries": {"en": "Rural households and families transitioning from conflict, especially those with existing livestock."}, "objectives": {"en": "Strengthen livestock-based livelihoods for peace-transition families.\nImprove animal health, productivity and household income."}, "activities": {"en": "Training on animal husbandry, feeding, vaccination and disease prevention.\nFarmer field schools and demonstration on improved fodder and shelter.\nLinkage to veterinary services and local markets."}, "results": {"en": "Reduced livestock mortality and improved productivity among trained households.\nDiversified income streams from dairy, poultry and meat production."}, "body": {"en": "<h2>Overview</h2><p>The project strengthens livestock-based livelihoods for rural and peace-transition families through training, animal-health outreach and market linkage.</p><h2>Target beneficiaries</h2><p>Rural households and families transitioning from conflict, especially those with existing livestock.</p><h2>Objectives</h2><ul><li>Strengthen livestock-based livelihoods for peace-transition families.</li><li>Improve animal health, productivity and household income.</li></ul><h2>Key activities</h2><ul><li>Training on animal husbandry, feeding, vaccination and disease prevention.</li><li>Farmer field schools and demonstration on improved fodder and shelter.</li><li>Linkage to veterinary services and local markets.</li></ul><h2>Results and impact</h2><ul><li>Reduced livestock mortality and improved productivity among trained households.</li><li>Diversified income streams from dairy, poultry and meat production.</li></ul><h2>Approach</h2><p>PYECSO combines classroom training with farmer field schools and follow-up coaching to make sure new practices stick.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p12-livestock-based-livelihoods-improvement';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "TVET", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Youth and adolescents (male and female where feasible) seeking skilled employment."}, "objectives": {"en": "Provide market-relevant TVET in tractor mechanics and welding.\nEnable youth transition into stable, skilled income opportunities."}, "activities": {"en": "Theory and hands-on training in mechanics and welding workshops.\nProvision of starter tool-kits and PPE on graduation.\nApprenticeship placement and market linkage support."}, "results": {"en": "Certified graduates entering paid work in local mechanics and welding shops.\nMeasurable income improvement for participating youth households."}, "body": {"en": "<h2>Overview</h2><p>This TVET project trains youth in tractor mechanics and welding, two trades in strong demand across rural Afghan markets.</p><h2>Target beneficiaries</h2><p>Youth and adolescents (male and female where feasible) seeking skilled employment.</p><h2>Objectives</h2><ul><li>Provide market-relevant TVET in tractor mechanics and welding.</li><li>Enable youth transition into stable, skilled income opportunities.</li></ul><h2>Key activities</h2><ul><li>Theory and hands-on training in mechanics and welding workshops.</li><li>Provision of starter tool-kits and PPE on graduation.</li><li>Apprenticeship placement and market linkage support.</li></ul><h2>Results and impact</h2><ul><li>Certified graduates entering paid work in local mechanics and welding shops.</li><li>Measurable income improvement for participating youth households.</li></ul><h2>Approach</h2><p>Curriculum is co-designed with local employers and paired with apprenticeship placement to smooth the transition from training to income.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p13-tractor-mechanics-welder-training';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "TVET", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Youth and families transitioning to peace, including ex-combatants and returnees."}, "objectives": {"en": "Support reintegration and reconciliation through economic empowerment.\nProvide vocational skills in construction trades (carpentry, masonry)."}, "activities": {"en": "Carpentry and masonry training with certified instructors.\nPeace-building and life-skills sessions integrated into the curriculum.\nPost-training tool-kits and job-placement support."}, "results": {"en": "Trained youth engaged in local reconstruction and small-business work.\nContributed to community-level reconciliation and stability."}, "body": {"en": "<h2>Overview</h2><p>The project supports national reconciliation by pairing vocational training with peace-building and life-skills for youth and families transitioning to peace.</p><h2>Target beneficiaries</h2><p>Youth and families transitioning to peace, including ex-combatants and returnees.</p><h2>Objectives</h2><ul><li>Support reintegration and reconciliation through economic empowerment.</li><li>Provide vocational skills in construction trades (carpentry, masonry).</li></ul><h2>Key activities</h2><ul><li>Carpentry and masonry training with certified instructors.</li><li>Peace-building and life-skills sessions integrated into the curriculum.</li><li>Post-training tool-kits and job-placement support.</li></ul><h2>Results and impact</h2><ul><li>Trained youth engaged in local reconstruction and small-business work.</li><li>Contributed to community-level reconciliation and stability.</li></ul><h2>Approach</h2><p>PYECSO integrates conflict-sensitive programming and gender-responsive facilitation throughout the training cycle.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p14-national-reconciliation-vocational-skills-training';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "TVET", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Women, girls and adolescents with limited access to education and employment."}, "objectives": {"en": "Empower women and girls through vocational skills.\nEnable home-based income generation in tailoring and light carpentry."}, "activities": {"en": "Structured tailoring and carpentry curricula delivered by female trainers where possible.\nProvision of sewing machines and basic carpentry tool-kits on graduation.\nFinancial literacy and small-business coaching."}, "results": {"en": "Graduates operating home-based enterprises and contributing to household income.\nIncreased self-confidence and community recognition of women''s economic role."}, "body": {"en": "<h2>Overview</h2><p>Vocational training for women and girls in tailoring and carpentry, designed to enable dignified home-based income generation.</p><h2>Target beneficiaries</h2><p>Women, girls and adolescents with limited access to education and employment.</p><h2>Objectives</h2><ul><li>Empower women and girls through vocational skills.</li><li>Enable home-based income generation in tailoring and light carpentry.</li></ul><h2>Key activities</h2><ul><li>Structured tailoring and carpentry curricula delivered by female trainers where possible.</li><li>Provision of sewing machines and basic carpentry tool-kits on graduation.</li><li>Financial literacy and small-business coaching.</li></ul><h2>Results and impact</h2><ul><li>Graduates operating home-based enterprises and contributing to household income.</li><li>Increased self-confidence and community recognition of women''s economic role.</li></ul><h2>Approach</h2><p>Delivered in safe spaces with female trainers and community engagement to secure family and elder support for women''s participation.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p15-professional-vocational-training-for-women';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Capacity Building", "location": "National", "country": "Afghanistan", "target_beneficiaries": {"en": "PYECSO staff — particularly female leaders — and partner community-based organisations."}, "objectives": {"en": "Strengthen internal systems, safeguarding and financial management.\nGrow the leadership pipeline of female staff and partners."}, "activities": {"en": "Organisational capacity assessment and improvement roadmap.\nWorkshops on PSEA, gender, MEAL, procurement and reporting.\nMentoring for female managers and partner CBOs."}, "results": {"en": "Upgraded systems and SOPs meeting international donor standards.\nStronger female leadership at management and field levels."}, "body": {"en": "<h2>Overview</h2><p>A small-grant partnership focused on strengthening PYECSO''s institutional systems and building the leadership pipeline of female staff and partner CBOs.</p><h2>Target beneficiaries</h2><p>PYECSO staff — particularly female leaders — and partner community-based organisations.</p><h2>Objectives</h2><ul><li>Strengthen internal systems, safeguarding and financial management.</li><li>Grow the leadership pipeline of female staff and partners.</li></ul><h2>Key activities</h2><ul><li>Organisational capacity assessment and improvement roadmap.</li><li>Workshops on PSEA, gender, MEAL, procurement and reporting.</li><li>Mentoring for female managers and partner CBOs.</li></ul><h2>Results and impact</h2><ul><li>Upgraded systems and SOPs meeting international donor standards.</li><li>Stronger female leadership at management and field levels.</li></ul><h2>Approach</h2><p>Combines assessment, training, coaching and roll-out of updated SOPs to ensure lasting institutional change.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p16-small-grant-partnerships-organizational-capacity-building';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Agriculture", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Smallholder farmers whose practices informed the design of subsequent agricultural programming."}, "objectives": {"en": "Generate evidence on prevailing farming practices, constraints and opportunities.\nInform the design of demand-driven agricultural interventions."}, "activities": {"en": "Household and key-informant surveys across selected districts.\nFocus-group discussions with male and female farmers.\nData analysis and dissemination workshop with partners."}, "results": {"en": "Evidence base used to shape PYECSO''s follow-up seed, livestock and training projects.\nImproved targeting and appropriateness of agricultural programming."}, "body": {"en": "<h2>Overview</h2><p>An evidence-generation project mapping farming practices, constraints and opportunities to inform PYECSO''s agricultural programming.</p><h2>Target beneficiaries</h2><p>Smallholder farmers whose practices informed the design of subsequent agricultural programming.</p><h2>Objectives</h2><ul><li>Generate evidence on prevailing farming practices, constraints and opportunities.</li><li>Inform the design of demand-driven agricultural interventions.</li></ul><h2>Key activities</h2><ul><li>Household and key-informant surveys across selected districts.</li><li>Focus-group discussions with male and female farmers.</li><li>Data analysis and dissemination workshop with partners.</li></ul><h2>Results and impact</h2><ul><li>Evidence base used to shape PYECSO''s follow-up seed, livestock and training projects.</li><li>Improved targeting and appropriateness of agricultural programming.</li></ul><h2>Approach</h2><p>Mixed-methods research with gender-disaggregated data and community feedback.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p17-agricultural-practices-survey';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Agriculture", "location": "Rural districts", "country": "Afghanistan", "target_beneficiaries": {"en": "Smallholder farming households, including female-headed and returnee families."}, "objectives": {"en": "Restore and diversify agricultural production at household level.\nStrengthen food security through home-grown vegetables and fruit trees."}, "activities": {"en": "Distribution of quality seeds and orchard saplings.\nTraining on planting, irrigation, pest management and post-harvest handling.\nFollow-up monitoring across the growing season."}, "results": {"en": "Increased household production of staple and horticultural crops.\nImproved dietary diversity and small surplus for local markets."}, "body": {"en": "<h2>Overview</h2><p>Seeds and orchard saplings distributed to villagers alongside training and season-long monitoring to rebuild household food production.</p><h2>Target beneficiaries</h2><p>Smallholder farming households, including female-headed and returnee families.</p><h2>Objectives</h2><ul><li>Restore and diversify agricultural production at household level.</li><li>Strengthen food security through home-grown vegetables and fruit trees.</li></ul><h2>Key activities</h2><ul><li>Distribution of quality seeds and orchard saplings.</li><li>Training on planting, irrigation, pest management and post-harvest handling.</li><li>Follow-up monitoring across the growing season.</li></ul><h2>Results and impact</h2><ul><li>Increased household production of staple and horticultural crops.</li><li>Improved dietary diversity and small surplus for local markets.</li></ul><h2>Approach</h2><p>Farmer-to-farmer learning and lead-farmer demonstration plots reinforce adoption of improved practices.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p18-seeds-plants-distribution-to-villagers';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Protection & Hygiene", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Local butchers and, indirectly, consumers relying on safer meat supply."}, "objectives": {"en": "Improve hygiene and safe handling practices in local meat supply chains.\nReduce risk of food-borne illness in target communities."}, "activities": {"en": "Training workshops on slaughter hygiene, cold-chain and meat preservation.\nProvision of basic hygiene supplies to participating shops.\nPublic awareness on safe meat handling at household level."}, "results": {"en": "Trained butchers applying improved hygiene practices in their shops.\nCommunity awareness of safe meat handling raised in target districts."}, "body": {"en": "<h2>Overview</h2><p>Hygiene training for butchers combined with community awareness on safe meat handling to reduce food-borne illness risk.</p><h2>Target beneficiaries</h2><p>Local butchers and, indirectly, consumers relying on safer meat supply.</p><h2>Objectives</h2><ul><li>Improve hygiene and safe handling practices in local meat supply chains.</li><li>Reduce risk of food-borne illness in target communities.</li></ul><h2>Key activities</h2><ul><li>Training workshops on slaughter hygiene, cold-chain and meat preservation.</li><li>Provision of basic hygiene supplies to participating shops.</li><li>Public awareness on safe meat handling at household level.</li></ul><h2>Results and impact</h2><ul><li>Trained butchers applying improved hygiene practices in their shops.</li><li>Community awareness of safe meat handling raised in target districts.</li></ul><h2>Approach</h2><p>Practical, shop-based training complemented by community outreach on food safety.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p19-meat-preservation-hygiene-training-for-butchers';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Cash & In-Kind", "location": "Rural & remote communities", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced families in rural and remote areas, prioritising children and elderly."}, "objectives": {"en": "Protect displaced families from winter cold in underserved locations.\nEnsure dignified in-kind support tailored to household composition."}, "activities": {"en": "Procurement of coats, blankets, boots and thermal wear.\nCommunity-based targeting and household verification.\nOn-site distribution with segregated queues for women."}, "results": {"en": "Displaced households equipped with essential winter items.\nReduced cold-related illness among children and elderly."}, "body": {"en": "<h2>Overview</h2><p>Winter clothing distribution for displaced households in rural and remote communities, prioritising children and elderly.</p><h2>Target beneficiaries</h2><p>Displaced families in rural and remote areas, prioritising children and elderly.</p><h2>Objectives</h2><ul><li>Protect displaced families from winter cold in underserved locations.</li><li>Ensure dignified in-kind support tailored to household composition.</li></ul><h2>Key activities</h2><ul><li>Procurement of coats, blankets, boots and thermal wear.</li><li>Community-based targeting and household verification.</li><li>On-site distribution with segregated queues for women.</li></ul><h2>Results and impact</h2><ul><li>Displaced households equipped with essential winter items.</li><li>Reduced cold-related illness among children and elderly.</li></ul><h2>Approach</h2><p>Community-based targeting and gender-sensitive site management ensure dignified access.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p2-winter-clothes-distribution-to-displaced-people';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Ongoing", "category": "Health & Nutrition", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Pregnant and lactating women, children under five, and children with special needs."}, "objectives": {"en": "Improve maternal and child health outcomes at community level.\nBoost routine immunisation and nutrition education coverage."}, "activities": {"en": "Health and nutrition education sessions.\nGrowth monitoring, immunisation outreach and micronutrient supplementation.\nReferral of complicated cases to health facilities."}, "results": {"en": "Improved maternal and child health indicators in target sites.\nHigher immunisation coverage and earlier detection of malnutrition."}, "body": {"en": "<h2>Overview</h2><p>A community-level maternal and child health programme combining education, growth monitoring, immunisation outreach and referral.</p><h2>Target beneficiaries</h2><p>Pregnant and lactating women, children under five, and children with special needs.</p><h2>Objectives</h2><ul><li>Improve maternal and child health outcomes at community level.</li><li>Boost routine immunisation and nutrition education coverage.</li></ul><h2>Key activities</h2><ul><li>Health and nutrition education sessions.</li><li>Growth monitoring, immunisation outreach and micronutrient supplementation.</li><li>Referral of complicated cases to health facilities.</li></ul><h2>Results and impact</h2><ul><li>Improved maternal and child health indicators in target sites.</li><li>Higher immunisation coverage and earlier detection of malnutrition.</li></ul><h2>Approach</h2><p>Delivered through trained female community health workers and integrated with existing health-facility referral pathways.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p20-maternal-child-health-program';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Ongoing", "category": "Health & Protection", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Women, girls and survivors of gender-based violence."}, "objectives": {"en": "Provide safe, accessible MHPSS to women and girls.\nStrengthen community-level protection and referral pathways."}, "activities": {"en": "Individual and group MHPSS counselling with trained female counsellors.\nSafe-space activities for adolescent girls.\nCase management and referral to health, legal and protection services."}, "results": {"en": "Women and girls reporting reduced distress and improved coping.\nStronger community-level referral pathways established."}, "body": {"en": "<h2>Overview</h2><p>Mental-health and psychosocial support for women, girls and survivors of gender-based violence, delivered in safe spaces by trained female counsellors.</p><h2>Target beneficiaries</h2><p>Women, girls and survivors of gender-based violence.</p><h2>Objectives</h2><ul><li>Provide safe, accessible MHPSS to women and girls.</li><li>Strengthen community-level protection and referral pathways.</li></ul><h2>Key activities</h2><ul><li>Individual and group MHPSS counselling with trained female counsellors.</li><li>Safe-space activities for adolescent girls.</li><li>Case management and referral to health, legal and protection services.</li></ul><h2>Results and impact</h2><ul><li>Women and girls reporting reduced distress and improved coping.</li><li>Stronger community-level referral pathways established.</li></ul><h2>Approach</h2><p>Confidential, survivor-centred practice aligned with international MHPSS and GBV standards.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p21-mental-health-psychosocial-support-mhpss';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Cash Assistance", "location": "Border & host districts", "country": "Afghanistan", "target_beneficiaries": {"en": "Undocumented returnees and conflict-affected families in host communities."}, "objectives": {"en": "Provide immediate, dignified cash support to returnees and conflict-affected families.\nReduce negative coping strategies during acute displacement."}, "activities": {"en": "Rapid household assessment and vulnerability scoring.\nCash transfers via hawala and secure payment agents.\nPost-distribution monitoring and grievance handling."}, "results": {"en": "Immediate cash reached hundreds of returnee and conflict-affected households.\nReduced reliance on debt, child labour and other negative coping."}, "body": {"en": "<h2>Overview</h2><p>Cash assistance for undocumented returnees and conflict-affected families in host communities near border crossings.</p><h2>Target beneficiaries</h2><p>Undocumented returnees and conflict-affected families in host communities.</p><h2>Objectives</h2><ul><li>Provide immediate, dignified cash support to returnees and conflict-affected families.</li><li>Reduce negative coping strategies during acute displacement.</li></ul><h2>Key activities</h2><ul><li>Rapid household assessment and vulnerability scoring.</li><li>Cash transfers via hawala and secure payment agents.</li><li>Post-distribution monitoring and grievance handling.</li></ul><h2>Results and impact</h2><ul><li>Immediate cash reached hundreds of returnee and conflict-affected households.</li><li>Reduced reliance on debt, child labour and other negative coping.</li></ul><h2>Approach</h2><p>Cash modality chosen to preserve household choice and dignity; verified end-to-end with PDM.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p3-community-support-for-immigrants-cash-assistance';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Cash Assistance", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Widows, orphans, daily wage labourers and persons with disabilities."}, "objectives": {"en": "Provide life-saving winter cash to the most vulnerable.\nEnable households to prioritise essential needs (food, fuel, medicine)."}, "activities": {"en": "Community-based vulnerability targeting.\nMulti-purpose cash transfers.\nPost-distribution monitoring and complaints handling."}, "results": {"en": "Winter cash reached the most vulnerable households across targeted provinces.\nDocumented reductions in negative coping at PDM."}, "body": {"en": "<h2>Overview</h2><p>Emergency winter cash for widows, orphans, daily-wage labourers and persons with disabilities in targeted provinces.</p><h2>Target beneficiaries</h2><p>Widows, orphans, daily wage labourers and persons with disabilities.</p><h2>Objectives</h2><ul><li>Provide life-saving winter cash to the most vulnerable.</li><li>Enable households to prioritise essential needs (food, fuel, medicine).</li></ul><h2>Key activities</h2><ul><li>Community-based vulnerability targeting.</li><li>Multi-purpose cash transfers.</li><li>Post-distribution monitoring and complaints handling.</li></ul><h2>Results and impact</h2><ul><li>Winter cash reached the most vulnerable households across targeted provinces.</li><li>Documented reductions in negative coping at PDM.</li></ul><h2>Approach</h2><p>Community-based targeting with elders, mullahs and female mobilisers safeguards dignity and inclusion.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p4-winter-emergency-cash-distribution';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced and remote rural communities."}, "objectives": {"en": "Provide immediate food relief to displaced and remote populations.\nBridge critical food gaps in inaccessible areas."}, "activities": {"en": "Procurement and quality control of wheat, rice and oil.\nLogistics to remote distribution points and community handover.\nVerification and post-distribution monitoring."}, "results": {"en": "Food packages reached hundreds of displaced and remote households.\nImmediate reduction in reported hunger and negative coping."}, "body": {"en": "<h2>Overview</h2><p>General food distribution of staple packages (wheat, rice, oil) to displaced and remote rural communities.</p><h2>Target beneficiaries</h2><p>Displaced and remote rural communities.</p><h2>Objectives</h2><ul><li>Provide immediate food relief to displaced and remote populations.</li><li>Bridge critical food gaps in inaccessible areas.</li></ul><h2>Key activities</h2><ul><li>Procurement and quality control of wheat, rice and oil.</li><li>Logistics to remote distribution points and community handover.</li><li>Verification and post-distribution monitoring.</li></ul><h2>Results and impact</h2><ul><li>Food packages reached hundreds of displaced and remote households.</li><li>Immediate reduction in reported hunger and negative coping.</li></ul><h2>Approach</h2><p>Community-based targeting and transparent verification underpin every distribution.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p5-general-food-distribution';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food & Education", "location": "Multi-province", "country": "Afghanistan", "target_beneficiaries": {"en": "Families transitioning to peace and vulnerable school-age children."}, "objectives": {"en": "Combine food relief with education support for children in fragile households.\nEncourage school attendance through provision of learning materials."}, "activities": {"en": "Distribution of food packages alongside student stationery kits.\nCommunity messaging on the value of continued schooling."}, "results": {"en": "Households received food relief and children received essential learning materials.\nImproved reported school attendance among beneficiary children."}, "body": {"en": "<h2>Overview</h2><p>A combined food and stationery distribution aimed at protecting children''s schooling in fragile households transitioning to peace.</p><h2>Target beneficiaries</h2><p>Families transitioning to peace and vulnerable school-age children.</p><h2>Objectives</h2><ul><li>Combine food relief with education support for children in fragile households.</li><li>Encourage school attendance through provision of learning materials.</li></ul><h2>Key activities</h2><ul><li>Distribution of food packages alongside student stationery kits.</li><li>Community messaging on the value of continued schooling.</li></ul><h2>Results and impact</h2><ul><li>Households received food relief and children received essential learning materials.</li><li>Improved reported school attendance among beneficiary children.</li></ul><h2>Approach</h2><p>Delivered with dignity in coordination with schools, elders and female mobilisers.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p6-food-stationery-distribution';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "Nangarhar (Jalalabad)", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced households and families transitioning to peace in Jalalabad area."}, "objectives": {"en": "Provide targeted food assistance to displaced families in the Jalalabad area.\nSupport stability of peace-transition households."}, "activities": {"en": "Procurement, transport and distribution of basic food supplies.\nCommunity-based targeting and PDM."}, "results": {"en": "Hundreds of Jalalabad-area households supported with essential food.\nReduced acute food insecurity in targeted sites."}, "body": {"en": "<h2>Overview</h2><p>Food distribution focused on Jalalabad and surrounding districts of Nangarhar for displaced and peace-transition families.</p><h2>Target beneficiaries</h2><p>Displaced households and families transitioning to peace in Jalalabad area.</p><h2>Objectives</h2><ul><li>Provide targeted food assistance to displaced families in the Jalalabad area.</li><li>Support stability of peace-transition households.</li></ul><h2>Key activities</h2><ul><li>Procurement, transport and distribution of basic food supplies.</li><li>Community-based targeting and PDM.</li></ul><h2>Results and impact</h2><ul><li>Hundreds of Jalalabad-area households supported with essential food.</li><li>Reduced acute food insecurity in targeted sites.</li></ul><h2>Approach</h2><p>Coordinated with local authorities and shuras for access, verification and dignified handover.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p7-food-distribution-jalalabad';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food Assistance", "location": "Laghman", "country": "Afghanistan", "target_beneficiaries": {"en": "Displaced families and families of martyrs in Laghman."}, "objectives": {"en": "Provide life-saving food to displaced and bereaved families in Laghman."}, "activities": {"en": "Distribution of primary food materials (grains, oil).\nCommunity-based targeting and PDM."}, "results": {"en": "Displaced and bereaved families in Laghman received essential food support."}, "body": {"en": "<h2>Overview</h2><p>Primary food materials distributed to displaced households and families of martyrs across Laghman province.</p><h2>Target beneficiaries</h2><p>Displaced families and families of martyrs in Laghman.</p><h2>Objectives</h2><ul><li>Provide life-saving food to displaced and bereaved families in Laghman.</li></ul><h2>Key activities</h2><ul><li>Distribution of primary food materials (grains, oil).</li><li>Community-based targeting and PDM.</li></ul><h2>Results and impact</h2><ul><li>Displaced and bereaved families in Laghman received essential food support.</li></ul><h2>Approach</h2><p>Community-based targeting, transparent verification and post-distribution monitoring.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p8-food-distribution-laghman';
UPDATE public.content_items SET data = COALESCE(data, '{}'::jsonb) || '{"status": "Completed", "category": "Food & Education", "location": "Logar & Kunar", "country": "Afghanistan", "target_beneficiaries": {"en": "Youth, adolescents and rural communities in Logar and Kunar provinces."}, "objectives": {"en": "Combine food relief with learning materials in Logar and Kunar.\nSupport continued education in fragile communities."}, "activities": {"en": "Joint food and stationery distributions in schools and community centres.\nCommunity engagement on school attendance and child protection."}, "results": {"en": "Youth and rural households in Logar and Kunar received combined food and education support.\nImproved school attendance reported in target sites."}, "body": {"en": "<h2>Overview</h2><p>Combined food and stationery distribution in Logar and Kunar supporting continued education in fragile communities.</p><h2>Target beneficiaries</h2><p>Youth, adolescents and rural communities in Logar and Kunar provinces.</p><h2>Objectives</h2><ul><li>Combine food relief with learning materials in Logar and Kunar.</li><li>Support continued education in fragile communities.</li></ul><h2>Key activities</h2><ul><li>Joint food and stationery distributions in schools and community centres.</li><li>Community engagement on school attendance and child protection.</li></ul><h2>Results and impact</h2><ul><li>Youth and rural households in Logar and Kunar received combined food and education support.</li><li>Improved school attendance reported in target sites.</li></ul><h2>Approach</h2><p>Delivered with dignity in coordination with schools, elders and female mobilisers.</p>"}}'::jsonb, updated_at = now() WHERE type='project' AND slug='p9-food-stationery-distribution-logar-kunar';